class CandidateKnownInfeasible(ValueError):
    """A candidate-specific hard failure that may advance the frontier."""


class FeatureCutSystemFailure(RuntimeError):
    """A wiring, artifact, tool, or invariant failure that stops the run."""


class PreflightSemanticReplanReady(FeatureCutSystemFailure):
    """A persisted Gemini choice requires one clean route reconstruction.

    This is deliberately distinct from an ordinary candidate failure.  The
    first execution measures a problem without spending any paid visual work,
    Gemini selects among the immutable alternatives, and the caller starts the
    feature cut again so every downstream binding is derived from that one
    authorised route.  It is never a signal for local candidate promotion.
    """


def _frontier_execution_key(
    beat_id: str,
    candidate_id: str,
    candidate_execution_sha256: str | None,
) -> tuple[str, str, str]:
    return (
        beat_id,
        candidate_id,
        candidate_execution_sha256 or "legacy",
    )


def _frontier_execution_dir(
    frontier_root: Path,
    *,
    beat_id: str,
    candidate_id: str,
    candidate_execution_sha256: str | None,
) -> Path:
    execution_component = (
        candidate_execution_sha256
        if candidate_execution_sha256 is not None
        else "legacy"
    )
    return (
        frontier_root
        / beat_id
        / candidate_id
        / f"execution-{execution_component}"
    )


def _run_persisted_production_frontier(
    *,
    state_path: Path,
    beats: Sequence[RoundRobinFrontierBeat] | None,
    local_preflight: Callable[[RoundRobinFrontierAttempt], None],
    exact_event: Callable[[RoundRobinFrontierAttempt], None],
    grounding: Callable[
        [RoundRobinFrontierAttempt],
        str | tuple[str, str] | None,
    ],
    resolve_deferred_on_exhaustion: (
        Callable[[str], str | tuple[str, str] | None] | None
    ) = None,
    resolve_deferred_batch: (
        Callable[
            [RoundRobinFrontierState],
            Mapping[str, str | tuple[str, str] | None],
        ]
        | None
    ) = None,
    allow_beat_omission: Callable[[str], bool] | None = None,
    on_frontier_frozen: (
        Callable[[RoundRobinFrontierState, Mapping[str, str]], None] | None
    ) = None,
    on_candidate_infeasible: (
        Callable[[RoundRobinFrontierAttempt, CandidateKnownInfeasible], None]
        | None
    ) = None,
    paid_interaction_counter: Callable[[], int] | None = None,
) -> Mapping[str, str]:
    """Drive one persisted production frontier without doing media work.

    The callbacks deliberately receive only the scheduler's admitted attempt.
    Candidate-specific infeasibility advances that candidate; every other
    exception stops immediately with the last completed state still durable.
    Rendering belongs in ``on_frontier_frozen`` so it cannot run while any
    beat still has frontier work.
    """

    if state_path.is_file():
        saved_state = read_json(state_path)
        if (
            isinstance(saved_state, Mapping)
            and saved_state.get("contract_version")
            == "round-robin-paid-frontier-v1"
        ):
            raise FeatureCutSystemFailure(
                "legacy round-robin frontier v1 cannot be resumed under "
                "hard-first source authority; use a fresh output namespace. "
                "No paid callback was dispatched and saved stage artifacts "
                "were not deleted"
            )
        state = RoundRobinFrontierState.model_validate(saved_state)
        if beats is not None:
            requested = initialize_round_robin_frontier(beats)
            persisted_specs = tuple(row.beat for row in state.beats)
            requested_specs = tuple(row.beat for row in requested.beats)
            if persisted_specs != requested_specs:
                raise FeatureCutSystemFailure(
                    "persisted production frontier does not match requested "
                    "beat and candidate bindings"
                )
    else:
        if beats is None:
            raise FeatureCutSystemFailure(
                "production frontier cannot start without beat bindings"
            )
        state = initialize_round_robin_frontier(beats)
        write_json(state_path, state)

    callbacks = {
        "local_preflight": local_preflight,
        "exact_event": exact_event,
        "grounding": grounding,
    }
    pass_outcomes = {
        "local_preflight": "local_preflight_passed",
        "exact_event": "exact_event_passed",
        "grounding": "grounding_accepted",
    }
    failure_outcomes = {
        "local_preflight": "local_preflight_failed",
        "exact_event": "exact_event_failed",
        "grounding": "grounding_failed",
    }

    if (
        resolve_deferred_on_exhaustion is not None
        and resolve_deferred_batch is not None
    ):
        raise ValueError(
            "frontier supports either per-beat or grouped deferred resolution"
        )

    preexisting_exhausted = [
        row.beat.beat_id
        for row in state.beats
        if row.status == "exhausted"
    ]
    if (
        resolve_deferred_on_exhaustion is not None
        and preexisting_exhausted
    ):
        raise FeatureCutSystemFailure(
            "persisted production frontier already contains exhausted beats "
            "from an older execution contract; use a fresh output namespace "
            "before any lower-priority or paid callback can run: "
            + ", ".join(preexisting_exhausted)
        )

    while (
        attempt := next_round_robin_frontier_attempt(state)
    ) is not None:
        accepted_candidate_id: str | None = None
        accepted_candidate_execution_sha256: str | None = None
        beat_omitted = False
        paid_count_before = (
            paid_interaction_counter()
            if paid_interaction_counter is not None
            else None
        )
        try:
            callback_result = callbacks[attempt.stage](attempt)
            if isinstance(callback_result, tuple):
                (
                    accepted_candidate_id,
                    accepted_candidate_execution_sha256,
                ) = callback_result
            else:
                accepted_candidate_id = callback_result
            if (
                accepted_candidate_id is not None
                and attempt.stage != "grounding"
            ):
                raise FeatureCutSystemFailure(
                    "only grounding may accept a constructed fallback"
                )
            outcome = pass_outcomes[attempt.stage]
            decision_codes = (f"{attempt.stage}_passed",)
        except CandidateKnownInfeasible as error:
            if on_candidate_infeasible is not None:
                on_candidate_infeasible(attempt, error)
            outcome = failure_outcomes[attempt.stage]
            decision_codes = (
                f"{attempt.stage}_candidate_known_infeasible",
                str(error),
            )
            beat_state = next(
                row
                for row in state.beats
                if row.beat.beat_id == attempt.beat_id
            )
            if (
                resolve_deferred_on_exhaustion is not None
                and beat_state.candidate_cursor + 1
                >= len(beat_state.beat.candidates)
            ):
                deferred_result = (
                    resolve_deferred_on_exhaustion(attempt.beat_id)
                )
                if isinstance(deferred_result, tuple):
                    (
                        accepted_candidate_id,
                        accepted_candidate_execution_sha256,
                    ) = deferred_result
                else:
                    accepted_candidate_id = deferred_result
                if accepted_candidate_id is not None:
                    decision_codes = (
                        *decision_codes,
                        "earlier_deferred_fallback_accepted_before_next_"
                        "priority_tier",
                    )
                elif (
                    allow_beat_omission is not None
                    and allow_beat_omission(attempt.beat_id)
                ):
                    beat_omitted = True
                    decision_codes = (
                        *decision_codes,
                        "policy_authorized_optional_beat_omission",
                    )
        except Exception as error:
            raise FeatureCutSystemFailure(
                "production frontier stopped on a non-candidate system "
                f"failure at {attempt.beat_id}/{attempt.candidate_id}/"
                f"{attempt.stage}: {type(error).__name__}:{error}"
            ) from error
        paid_calls_added = (
            None
            if paid_count_before is None
            else max(0, paid_interaction_counter() - paid_count_before)
        )

        state = record_round_robin_frontier_attempt(
            state,
            RoundRobinFrontierAttemptResult(
                attempt=attempt,
                outcome=outcome,
                accepted_candidate_id=accepted_candidate_id,
                accepted_candidate_execution_sha256=(
                    accepted_candidate_execution_sha256
                ),
                beat_omitted=beat_omitted,
                decision_codes=decision_codes,
                paid_calls_added=paid_calls_added,
            ),
        )
        write_json(state_path, state)
        just_updated = next(
            row
            for row in state.beats
            if row.beat.beat_id == attempt.beat_id
        )
        if (
            just_updated.status == "exhausted"
            and resolve_deferred_batch is None
        ):
            raise FeatureCutSystemFailure(
                "production frontier exhausted a non-omittable beat before any "
                "lower-priority callback could run: "
                + attempt.beat_id
            )

    unresolved_exhausted = [
        row.beat.beat_id
        for row in state.beats
        if row.status == "exhausted"
    ]
    if resolve_deferred_batch is not None and unresolved_exhausted:
        paid_count_before = (
            paid_interaction_counter()
            if paid_interaction_counter is not None
            else None
        )
        batch_resolutions = resolve_deferred_batch(state)
        paid_calls_added = (
            None
            if paid_count_before is None
            else max(0, paid_interaction_counter() - paid_count_before)
        )
        resolved_beats = list(state.beats)
        batch_results: list[RoundRobinFrontierAttemptResult] = []
        for beat_index, beat_state in enumerate(resolved_beats):
            if beat_state.status != "exhausted":
                continue
            resolution = batch_resolutions.get(beat_state.beat.beat_id)
            if isinstance(resolution, tuple):
                candidate_id, execution_sha256 = resolution
            elif isinstance(resolution, str):
                candidate_id, execution_sha256 = resolution, None
            else:
                candidate_id, execution_sha256 = None, None
            if candidate_id is None:
                if allow_beat_omission is None or not allow_beat_omission(
                    beat_state.beat.beat_id
                ):
                    raise FeatureCutSystemFailure(
                        "grouped deferred resolver left a non-omittable beat "
                        "unresolved: " + beat_state.beat.beat_id
                    )
                resolved_beats[beat_index] = beat_state.model_copy(
                    update={"status": "omitted"}
                )
                continue
            matching_candidates = [
                candidate
                for candidate in beat_state.beat.candidates
                if candidate.candidate_id == candidate_id
                and (
                    execution_sha256 is None
                    or candidate.candidate_execution_sha256 == execution_sha256
                )
            ]
            if len(matching_candidates) != 1:
                raise FeatureCutSystemFailure(
                    "grouped deferred resolver selected an unknown immutable "
                    "candidate for " + beat_state.beat.beat_id
                )
            selected = matching_candidates[0]
            resolved_beats[beat_index] = beat_state.model_copy(
                update={
                    "status": "accepted",
                    "active_candidate_id": None,
                    "active_candidate_execution_sha256": None,
                    "accepted_candidate_id": selected.candidate_id,
                    "accepted_candidate_execution_sha256": (
                        selected.candidate_execution_sha256
                    ),
                }
            )
            # A beat may continue measuring later route executions after an
            # earlier one reached grounding and was deferred for Gemini's
            # grouped decision.  Bind the acceptance to that selected
            # execution, not to the final (often local-preflight) attempt of
            # the whole beat.
            last_attempt = next(
                (
                    item.attempt
                    for item in reversed(state.attempt_history)
                    if item.attempt.beat_id == beat_state.beat.beat_id
                    and item.attempt.candidate_id == selected.candidate_id
                    and item.attempt.candidate_execution_sha256
                    == selected.candidate_execution_sha256
                ),
                None,
            )
            if last_attempt is None or last_attempt.stage != "grounding":
                raise FeatureCutSystemFailure(
                    "grouped deferred resolver has no terminal grounding "
                    "attempt for " + beat_state.beat.beat_id
                )
            batch_results.append(
                RoundRobinFrontierAttemptResult(
                    attempt=last_attempt,
                    outcome="grounding_failed",
                    accepted_candidate_id=selected.candidate_id,
                    accepted_candidate_execution_sha256=(
                        selected.candidate_execution_sha256
                    ),
                    paid_calls_added=(
                        paid_calls_added if not batch_results else 0
                    ),
                    decision_codes=(
                        "grouped_scoped_semantic_replan_selected_"
                        "immutable_option",
                    ),
                )
            )
        state = state.model_copy(
            update={
                "revision": state.revision + len(batch_results),
                "beats": tuple(resolved_beats),
                "attempt_history": (*state.attempt_history, *batch_results),
                "paid_calls_consumed": state.paid_calls_consumed
                + (paid_calls_added or 0),
            }
        )
        write_json(state_path, state)
        unresolved_exhausted = [
            row.beat.beat_id
            for row in state.beats
            if row.status == "exhausted"
        ]
    if resolve_deferred_on_exhaustion is not None and unresolved_exhausted:
        raise FeatureCutSystemFailure(
            "production frontier exhausted without a validated natural or "
            "constructed fallback: "
            + ", ".join(unresolved_exhausted)
        )

    accepted = {
        row.beat.beat_id: row.accepted_candidate_id
        for row in state.beats
        if (
            row.status == "accepted"
            and row.accepted_candidate_id is not None
        )
    }
    if on_frontier_frozen is not None:
        on_frontier_frozen(state, accepted)
    return accepted


def _frontier_stage_binding_sha256(
    *,
    beat_id: str,
    candidate_id: str,
    candidate_execution_sha256: str | None = None,
    stage: str,
    dependency_hashes: Sequence[str],
    policy_reference: str,
    route_sha256: str,
) -> str:
    """Bind one resumable stage only to candidate-scoped dependencies.

    The global route is intentionally excluded. Reassigning another beat
    changes the route hash but cannot change an already resolved exact frame
    or grounding result for this immutable candidate. The route remains in
    the artifact as audit metadata and is bound by the frozen selection.
    """

    binding = {
        "contract_version": (
            "vertical-frontier-stage-binding-v3"
            if candidate_execution_sha256 is not None
            else "vertical-frontier-stage-binding-v2"
        ),
        "beat_id": beat_id,
        "candidate_id": candidate_id,
        "stage": stage,
        "dependency_hashes": list(dependency_hashes),
        "policy_reference": policy_reference,
    }
    if candidate_execution_sha256 is not None:
        binding["candidate_execution_sha256"] = (
            candidate_execution_sha256
        )
    return hashlib.sha256(
        json.dumps(
            binding,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _legacy_frontier_stage_binding_sha256(
    *,
    beat_id: str,
    candidate_id: str,
    stage: str,
    dependency_hashes: Sequence[str],
    policy_reference: str,
    route_sha256: str,
) -> str:
    """Recompute the v1 binding so saved paid results can migrate locally."""

    return hashlib.sha256(
        json.dumps(
            {
                "contract_version": "vertical-frontier-stage-binding-v1",
                "beat_id": beat_id,
                "candidate_id": candidate_id,
                "stage": stage,
                "dependency_hashes": list(dependency_hashes),
                "policy_reference": policy_reference,
                "route_sha256": route_sha256,
            },
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _load_or_create_frontier_stage_artifact(
    *,
    artifact_path: Path,
    beat_id: str,
    candidate_id: str,
    candidate_execution_sha256: str | None = None,
    stage: str,
    dependency_hashes: Sequence[str],
    policy_reference: str,
    route_sha256: str,
    producer: Callable[[], Mapping[str, Any]],
    stale_local_recompile_producer: (
        Callable[[], Mapping[str, Any]] | None
    ) = None,
    stale_paid_payload_validator: (
        Callable[[Mapping[str, Any]], bool] | None
    ) = None,
) -> Mapping[str, Any]:
    """Persist a callback result before advancing scheduler state.

    A process may die after a paid provider response but before the frontier
    cursor advances.  The stage artifact is therefore the callback's durable
    commit point.  Resume validates every immutable dependency and returns the
    saved payload without invoking ``producer`` again.
    """

    binding_sha256 = _frontier_stage_binding_sha256(
        beat_id=beat_id,
        candidate_id=candidate_id,
        candidate_execution_sha256=candidate_execution_sha256,
        stage=stage,
        dependency_hashes=dependency_hashes,
        policy_reference=policy_reference,
        route_sha256=route_sha256,
    )
    if os.path.lexists(artifact_path) and (
        artifact_path.is_symlink() or not artifact_path.is_file()
    ):
        raise FeatureCutSystemFailure(
            "persisted vertical frontier stage artifact path exists but is "
            "not a regular file"
        )
    if artifact_path.is_file():
        saved = read_json(artifact_path)
        expected_definition = hashlib.sha256(
            json.dumps(
                {
                    key: value
                    for key, value in saved.items()
                    if key not in {"definition_sha256", "generated_at"}
                },
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        if saved.get("definition_sha256") != expected_definition:
            raise FeatureCutSystemFailure(
                "persisted vertical frontier stage artifact hash changed"
            )
        if (
            saved.get("contract_version")
            != "vertical-frontier-stage-artifact-v1"
            or saved.get("beat_id") != beat_id
            or saved.get("candidate_id") != candidate_id
            or saved.get("stage") != stage
            or (
                saved.get("candidate_execution_sha256") is not None
                and saved.get("candidate_execution_sha256")
                != candidate_execution_sha256
            )
        ):
            raise FeatureCutSystemFailure(
                "persisted vertical frontier stage artifact has stale or "
                "tampered bindings: "
                f"{beat_id}/{candidate_id}/{stage}@{artifact_path}"
            )
        payload = saved.get("payload")
        if not isinstance(payload, Mapping):
            raise FeatureCutSystemFailure(
                "persisted vertical frontier stage artifact has no payload"
            )
        saved_dependency_hashes = saved.get("dependency_hashes")
        saved_policy_reference = saved.get("policy_reference")
        saved_route_sha256 = saved.get("route_sha256")
        if (
            not isinstance(saved_dependency_hashes, list)
            or not all(
                isinstance(value, str)
                for value in saved_dependency_hashes
            )
            or not isinstance(saved_policy_reference, str)
            or not isinstance(saved_route_sha256, str)
        ):
            raise FeatureCutSystemFailure(
                "persisted vertical frontier stage artifact has stale or "
                "tampered bindings: "
                f"{beat_id}/{candidate_id}/{stage}@{artifact_path}"
            )
        saved_v2_binding = _frontier_stage_binding_sha256(
            beat_id=beat_id,
            candidate_id=candidate_id,
            candidate_execution_sha256=(
                saved.get("candidate_execution_sha256")
            ),
            stage=stage,
            dependency_hashes=saved_dependency_hashes,
            policy_reference=saved_policy_reference,
            route_sha256=saved_route_sha256,
        )
        saved_legacy_binding = _legacy_frontier_stage_binding_sha256(
            beat_id=beat_id,
            candidate_id=candidate_id,
            stage=stage,
            dependency_hashes=saved_dependency_hashes,
            policy_reference=saved_policy_reference,
            route_sha256=saved_route_sha256,
        )
        saved_binding_sha256 = saved.get("binding_sha256")
        if saved_binding_sha256 not in {
            saved_v2_binding,
            saved_legacy_binding,
        }:
            raise FeatureCutSystemFailure(
                "persisted vertical frontier stage artifact has stale or "
                "tampered bindings: "
                f"{beat_id}/{candidate_id}/{stage}@{artifact_path}"
            )
        bindings_are_stale = (
            saved_dependency_hashes != list(dependency_hashes)
            or saved_policy_reference != policy_reference
            or (
                saved.get("candidate_execution_sha256") is not None
                and saved.get("candidate_execution_sha256")
                != candidate_execution_sha256
            )
        )
        if bindings_are_stale:
            if (
                stale_paid_payload_validator is not None
                and stale_paid_payload_validator(payload)
            ):
                # A local wrapper revision may change its artifact hash while
                # leaving the exact provider input unchanged.  Keep the paid
                # artifact byte-identical, validate its semantic projection,
                # and record the narrow compatibility proof beside it.
                write_json(
                    artifact_path.with_name(
                        artifact_path.name + ".paid-input-compat.json"
                    ),
                    {
                        "contract_version": (
                            "vertical-frontier-paid-input-compat-v1"
                        ),
                        "artifact_path": str(artifact_path.resolve()),
                        "artifact_sha256": sha256_file(artifact_path),
                        "beat_id": beat_id,
                        "candidate_id": candidate_id,
                        "candidate_execution_sha256": (
                            candidate_execution_sha256
                        ),
                        "stage": stage,
                        "previous_dependency_hashes": (
                            saved_dependency_hashes
                        ),
                        "current_dependency_hashes": list(dependency_hashes),
                        "validation_scope": (
                            "exact_provider_input_projection_unchanged"
                        ),
                        "paid_provider_dispatch_added": False,
                        "generated_at": utc_now(),
                    },
                )
                return dict(payload)
            locally_recompilable = (
                stage in {"local_preflight", "finalize"}
                or (
                    stage == "grounding"
                    and stale_local_recompile_producer is not None
                )
            )
            if not locally_recompilable:
                raise FeatureCutSystemFailure(
                    "persisted vertical frontier stage artifact has stale or "
                    "tampered bindings: "
                    f"{beat_id}/{candidate_id}/{stage}@{artifact_path}"
                )
            archive_dir = artifact_path.parent / "archive"
            archive_dir.mkdir(parents=True, exist_ok=True)
            archived_path = archive_dir / (
                artifact_path.stem
                + ".stale-"
                + uuid.uuid4().hex
                + artifact_path.suffix
            )
            archived_sha256 = sha256_file(artifact_path)
            artifact_path.replace(archived_path)
            write_json(
                archived_path.with_name(
                    archived_path.name + ".archive-record.json"
                ),
                {
                    "contract_version": (
                        "zero-paid-frontier-stale-archive-v2"
                    ),
                    "stage": stage,
                    "beat_id": beat_id,
                    "candidate_id": candidate_id,
                    "archived_path": str(archived_path.resolve()),
                    "archived_sha256": archived_sha256,
                    "previous_dependency_hashes": saved_dependency_hashes,
                    "current_dependency_hashes": list(dependency_hashes),
                    "previous_policy_reference": saved_policy_reference,
                    "current_policy_reference": policy_reference,
                    "paid_provider_dispatch_added": False,
                    "recompile_mode": (
                        "local_preflight"
                        if stage == "local_preflight"
                        else "finalize_projection"
                        if stage == "finalize"
                        else "saved_provider_evidence_local_recompile"
                    ),
                    "generated_at": utc_now(),
                },
            )
            if stale_local_recompile_producer is not None:
                producer = stale_local_recompile_producer
        else:
            if saved_binding_sha256 == saved_legacy_binding:
                legacy_binding = saved_legacy_binding
                # Keep the paid artifact byte-identical: downstream stages
                # bind its complete file SHA. Compatibility metadata belongs
                # beside the artifact, never inside it.
                write_json(
                    artifact_path.with_name(
                        artifact_path.name + ".binding-v2-compat.json"
                    ),
                    {
                        "contract_version": (
                            "vertical-frontier-stage-binding-compat-v1"
                        ),
                        "artifact_path": str(artifact_path.resolve()),
                        "artifact_sha256": sha256_file(artifact_path),
                        "beat_id": beat_id,
                        "candidate_id": candidate_id,
                        "candidate_execution_sha256": (
                            candidate_execution_sha256
                        ),
                        "stage": stage,
                        "verified_legacy_binding_sha256": legacy_binding,
                        "current_binding_sha256": binding_sha256,
                        "migrated_from_route_sha256": saved_route_sha256,
                        "current_route_sha256": route_sha256,
                        "policy_reference": policy_reference,
                        "dependency_hashes": list(dependency_hashes),
                        "migration_scope": (
                            "route_only_with_identical_dependency_schema"
                        ),
                        "paid_provider_dispatch_added": False,
                    },
                )
            return dict(payload)

    produced = producer()
    if not isinstance(produced, Mapping):
        raise FeatureCutSystemFailure(
            "frontier stage producer returned a non-mapping payload"
        )
    payload = dict(produced)
    artifact = {
        "contract_version": "vertical-frontier-stage-artifact-v1",
        "beat_id": beat_id,
        "candidate_id": candidate_id,
        "candidate_execution_sha256": candidate_execution_sha256,
        "stage": stage,
        "binding_sha256": binding_sha256,
        "binding_contract_version": (
            "vertical-frontier-stage-binding-v3"
            if candidate_execution_sha256 is not None
            else "vertical-frontier-stage-binding-v2"
        ),
        "dependency_hashes": list(dependency_hashes),
        "policy_reference": policy_reference,
        "route_sha256": route_sha256,
        "payload": payload,
    }
    artifact["definition_sha256"] = hashlib.sha256(
        json.dumps(
            artifact,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    artifact["generated_at"] = utc_now()
    write_json(artifact_path, artifact)
    return payload


def _load_existing_frontier_stage_artifact(
    *,
    artifact_path: Path,
    beat_id: str,
    candidate_id: str,
    candidate_execution_sha256: str | None = None,
    stage: str,
    dependency_hashes: Sequence[str],
    policy_reference: str,
    route_sha256: str,
    stale_paid_payload_validator: (
        Callable[[Mapping[str, Any]], bool] | None
    ) = None,
) -> Mapping[str, Any]:
    """Validate an already committed stage without permitting provider work."""

    if not artifact_path.is_file():
        raise FeatureCutSystemFailure(
            "persisted vertical frontier stage artifact is missing after "
            f"the scheduler advanced: {beat_id}/{candidate_id}/{stage}"
        )

    def reject_producer() -> Mapping[str, Any]:
        raise FeatureCutSystemFailure(
            "load-only frontier validation attempted to dispatch a producer"
        )

    return _load_or_create_frontier_stage_artifact(
        artifact_path=artifact_path,
        beat_id=beat_id,
        candidate_id=candidate_id,
        candidate_execution_sha256=candidate_execution_sha256,
        stage=stage,
        dependency_hashes=dependency_hashes,
        policy_reference=policy_reference,
        route_sha256=route_sha256,
        producer=reject_producer,
        stale_paid_payload_validator=stale_paid_payload_validator,
    )


def _read_frontier_stage_payload_integrity_only(
    artifact_path: Path,
    *,
    beat_id: str,
    candidate_id: str,
    stage: str,
) -> Mapping[str, Any]:
    """Read prior audit facts without accepting a stale execution binding."""

    saved = read_json(artifact_path)
    expected_definition = hashlib.sha256(
        json.dumps(
            {
                key: value
                for key, value in saved.items()
                if key not in {"definition_sha256", "generated_at"}
            },
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    payload = saved.get("payload")
    if (
        saved.get("definition_sha256") != expected_definition
        or saved.get("contract_version")
        != "vertical-frontier-stage-artifact-v1"
        or saved.get("beat_id") != beat_id
        or saved.get("candidate_id") != candidate_id
        or saved.get("stage") != stage
        or not isinstance(payload, Mapping)
    ):
        raise FeatureCutSystemFailure(
            "persisted vertical frontier stage artifact failed integrity-only "
            f"audit: {beat_id}/{candidate_id}/{stage}@{artifact_path}"
        )
    return dict(payload)


def _validate_frozen_vertical_render_selection(
    *,
    frontier_root: Path,
    feature_id: str,
    candidate_id: str,
    candidate_execution_sha256: str,
) -> Mapping[str, Any]:
    """Prove that rendering consumes the exact frozen stage artifacts."""

    selection = read_json(frontier_root / "selection.json")
    definition = dict(selection)
    saved_definition_sha256 = definition.pop(
        "definition_sha256",
        None,
    )
    state = RoundRobinFrontierState.model_validate(
        read_json(frontier_root / "state.json")
    )
    selected_candidate_ids = dict(
        selection.get("selected_candidate_ids", {})
    )
    selected_candidate_execution_sha256s = dict(
        selection.get("selected_candidate_execution_sha256s", {})
    )
    omitted_feature_ids = set(selection.get("omitted_feature_ids", ()))
    state_selected_candidate_ids = {
        row.beat.beat_id: row.accepted_candidate_id
        for row in state.beats
        if row.status == "accepted"
        and row.accepted_candidate_id is not None
    }
    state_selected_candidate_execution_sha256s = {
        row.beat.beat_id: row.accepted_candidate_execution_sha256
        for row in state.beats
        if row.status == "accepted"
        and row.accepted_candidate_execution_sha256 is not None
    }
    state_omitted_feature_ids = {
        row.beat.beat_id
        for row in state.beats
        if row.status == "omitted"
    }
    state_resolution_invalid = (
        any(
            row.status not in {"accepted", "omitted"}
            for row in state.beats
        )
        or state_selected_candidate_ids != selected_candidate_ids
        or state_selected_candidate_execution_sha256s
        != selected_candidate_execution_sha256s
        or state_omitted_feature_ids != omitted_feature_ids
    )
    omission_reconciliation_path = (
        frontier_root / "omission-reconciliation.json"
    )
    omission_reconciliation_sha256 = selection.get(
        "omission_reconciliation_sha256"
    )
    omission_reconciliation_invalid = False
    if omitted_feature_ids:
        if (
            omission_reconciliation_sha256 is None
            or not omission_reconciliation_path.is_file()
        ):
            omission_reconciliation_invalid = True
        else:
            omission_reconciliation = read_json(
                omission_reconciliation_path
            )
            omission_reconciliation_invalid = (
                omission_reconciliation_sha256
                != sha256_file(omission_reconciliation_path)
                or omission_reconciliation.get("policy_reference")
                != selection.get("policy_reference")
                or set(
                    omission_reconciliation.get(
                        "omitted_feature_ids",
                        (),
                    )
                )
                != omitted_feature_ids
                or set(
                    omission_reconciliation.get(
                        "retained_feature_ids",
                        (),
                    )
                )
                != set(selected_candidate_ids)
                or omission_reconciliation.get("music_supplied") is not False
                or omission_reconciliation.get("horizontal_requested")
                is not False
                or omission_reconciliation.get("gates")
                != {
                    "duration": "passed",
                    "panel_fraction": "passed",
                    "music_reconciliation": "not_applicable",
                    "aspect_scope": "9:16_only",
                }
            )
    elif omission_reconciliation_sha256 is not None:
        omission_reconciliation_invalid = True
    candidate_binding = selection.get(
        "selected_candidates",
        {},
    ).get(feature_id, {})
    candidate_root = _frontier_execution_dir(
        frontier_root,
        beat_id=feature_id,
        candidate_id=candidate_id,
        candidate_execution_sha256=candidate_execution_sha256,
    )
    finalized_path = candidate_root / "finalized.json"
    finalized = (
        read_json(finalized_path)
        if finalized_path.is_file()
        else {}
    )
    finalized_definition = dict(finalized)
    finalized_saved_sha256 = finalized_definition.pop(
        "definition_sha256",
        None,
    )
    finalized_definition.pop("generated_at", None)
    finalized_dependencies = finalized.get("dependency_hashes", ())
    invalid = (
        saved_definition_sha256 != _stable_fingerprint(definition)
        or selection.get("state_sha256")
        != sha256_file(frontier_root / "state.json")
        or state_resolution_invalid
        or omission_reconciliation_invalid
        or not selection.get("all_beats_resolved")
        or not selection.get("render_permitted")
        or selected_candidate_ids.get(feature_id)
        != candidate_id
        or selected_candidate_execution_sha256s.get(feature_id)
        != candidate_execution_sha256
        or candidate_binding.get("candidate_execution_sha256")
        != candidate_execution_sha256
        or candidate_binding.get("local_artifact_sha256")
        != sha256_file(candidate_root / "local.json")
        or candidate_binding.get("exact_artifact_sha256")
        != sha256_file(candidate_root / "exact.json")
        or candidate_binding.get("geometry_artifact_sha256")
        != sha256_file(candidate_root / "geometry.json")
        or finalized.get("stage") != "finalize"
        or finalized_saved_sha256
        != _stable_fingerprint(finalized_definition)
        or len(finalized_dependencies) != 3
        or finalized_dependencies[0]
        != sha256_file(frontier_root / "selection.json")
        or finalized_dependencies[1]
        != sha256_file(candidate_root / "geometry.json")
        or next_round_robin_frontier_attempt(state) is not None
    )
    if invalid:
        raise FeatureCutSystemFailure(
            "vertical render attempted before the production frontier "
            "selection was completely frozen"
        )
    return selection


def _validate_all_vertical_finalizers_ready(
    frontier_root: Path,
) -> Mapping[str, Any]:
    """Block the first segment render until every selected beat finalized."""

    selection = read_json(frontier_root / "selection.json")
    selected_execution_sha256s = dict(
        selection.get("selected_candidate_execution_sha256s", {})
    )
    missing = []
    for feature_id, candidate_id in dict(
        selection.get("selected_candidate_ids", {})
    ).items():
        candidate_execution_sha256 = selected_execution_sha256s.get(
            feature_id
        )
        if not isinstance(candidate_execution_sha256, str) or not (
            _frontier_execution_dir(
                frontier_root,
                beat_id=feature_id,
                candidate_id=candidate_id,
                candidate_execution_sha256=candidate_execution_sha256,
            )
            / "finalized.json"
        ).is_file():
            missing.append(feature_id)
    if missing:
        raise FeatureCutSystemFailure(
            "autonomous vertical render batch started before all selected "
            "beats finalized: " + ", ".join(sorted(missing))
        )
    return selection


def _require_candidate_scoped_failure(error: Exception) -> None:
    """Reject broad fallback for system/invariant failures.

    Existing candidate solvers use ``ValueError`` for bounded infeasibility.
    Anything else is treated as a run-level fault instead of silently buying
    another candidate attempt.
    """

    if isinstance(error, ValueError):
        return
    raise FeatureCutSystemFailure(
        "candidate execution raised a non-candidate system failure: "
        f"{type(error).__name__}:{error}"
    ) from error


def _maskless_source_motion_preflight(
    *,
    source_path: Path,
    source_asset_id: str,
    window_start_ms: int,
    window_end_ms: int,
    output_dir: Path,
) -> SourceCameraMotionEvidence:
    """Measure high-confidence source defects before any paid geometry work.

    Without foreground masks a large moving subject may make the estimate
    unreliable.  That state remains unknown and proceeds to the masked
    post-SAM pass.  Only reliable dirty edges or isolated camera jolts are
    rejected here.
    """

    evidence = measure_source_camera_motion(
        source_path=source_path,
        source_asset_id=source_asset_id,
        window_start_ms=window_start_ms,
        window_end_ms=window_end_ms,
        subject_tracks=(),
        output_dir=output_dir,
    )
    if evidence.reliable and (
        evidence.isolated_jolt_count > 0
        or evidence.dirty_head
        or evidence.dirty_tail
    ):
        raise CandidateKnownInfeasible(
            "maskless source-motion preflight found an unresolved dirty "
            "edge or isolated camera jolt"
        )
    return evidence


